11	service AIService {
12	  // Transcribe transcribes an audio file using an instance AI provider.
13	  rpc Transcribe(TranscribeRequest) returns (TranscribeResponse) {
14	    option (google.api.http) = {
15	      post: "/api/v1/ai:transcribe"
16	      body: "*"
17	    };
18	    option (google.api.method_signature) = "audio";
19	  }
20	}
21	
22	message TranscribeRequest {
23	  // Required. Audio input.
24	  TranscriptionAudio audio = 1 [(google.api.field_behavior) = REQUIRED];
25	}
26	
27	message TranscriptionAudio {
28	  oneof source {
29	    // Inline audio bytes.
30	    bytes content = 1 [(google.api.field_behavior) = INPUT_ONLY];
31	
32	    // URI for audio content. Reserved for future use.
33	    string uri = 2;
34	  }
35	
36	  // Optional. The uploaded filename.
37	  string filename = 3 [(google.api.field_behavior) = OPTIONAL];
38	
39	  // Optional. The MIME type of the input audio.
40	  string content_type = 4 [(google.api.field_behavior) = OPTIONAL];
41	}
42	
43	message TranscribeResponse {
44	  // The transcribed text.
45	  string text = 1;
46	}
